def ship_within_days(weights, days):
    lo, hi = 1, sum(weights)
    while lo < hi:
        mid = (lo + hi) // 2
        needed = 1
        load = 0
        for w in weights:
            if load + w > mid:
                needed += 1
                load = 0
            load += w
        if needed <= days:
            hi = mid
        else:
            lo = mid + 1
    return lo
