def longest_univalue_path(root):
    best = 0
    def arm(node):
        nonlocal best
        if node is None:
            return 0
        la = arm(node.left)
        ra = arm(node.right)
        if node.left and node.left.val == node.val:
            la += 1
        if node.right and node.right.val == node.val:
            ra += 1
        best = max(best, la + ra)
        return max(la, ra)
    arm(root)
    return best
